/* @socom-skeleton body gridGetAtomBasePtr__Q23zdb5CGridFii */
namespace zdb {
CGridAtom** CGrid::gridGetAtomBasePtr(s32 x, s32 y)
    {
        u32 xCellCount = 0;
        u32 yCellCount = 0;
        u32 cellLength = 0;

        if (x < 0)
            x = 0;

        xCellCount = m_CellCount.cx;
        cellLength = xCellCount - 1;

        if (x <= cellLength)
            cellLength = x;

        if (y < 0)
            y = 0;

        yCellCount = m_CellCount.cy - 1;

        if (y <= yCellCount)
            yCellCount = y;

        return m_Atoms + cellLength + yCellCount * xCellCount;
    }
}

/* @socom-skeleton body gridAddNodeToGrids__Q23zdb5CGridFPQ23zdb5CNode */
/* @socom-skeleton body gridAddNodeToGrids__Q23zdb5CGridFPQ23zdb5CNode */
namespace zdb {
void CGrid::gridAddNodeToGrids(CNode* node)
    {
        /* 0x216a90: the node's bbox (its parent's with m_use_parent_bbox, the grandparent's
           when the parent also uses its parent's) in world space, shrunk by 1/10000 of its
           size per side, gives the cells it overlaps; one free atom per cell goes to the
           node and into that cell's list (head kept, new atoms after it). Was a TODO that
           inserted nothing. ELF quirk kept: an empty free list hands out a NULL atom. */
        if (node == NULL)
            return;

        const CBBox* bbox;

        if (!node->m_use_parent_bbox)
        {
            bbox = &node->m_bbox;
        }
        else
        {
            CNode* parent = node->m_parent;

            if (parent->m_use_parent_bbox)
                bbox = parent->m_parent->GetBBox();
            else
                bbox = &parent->m_bbox;
        }

        CPnt3D pts[2];
        node->m_matrix.Transform(&bbox->m_min, pts, 2);

        if (!(pts[0].x <= pts[1].x))
        {
            f32 swap = pts[0].x;
            pts[0].x = pts[1].x;
            pts[1].x = swap;
        }

        if (!(pts[0].y <= pts[1].y))
        {
            f32 swap = pts[0].y;
            pts[0].y = pts[1].y;
            pts[1].y = swap;
        }

        if (!(pts[0].z <= pts[1].z))
        {
            f32 swap = pts[0].z;
            pts[0].z = pts[1].z;
            pts[1].z = swap;
        }

        f32 shrinkZ = 0.0001f * (pts[1].z - pts[0].z);
        f32 shrinkX = 0.0001f * (pts[1].x - pts[0].x);

        s32 x0 = (s32)(m_InvCellDim * (shrinkX + (pts[0].x - m_origin.x)));
        if (x0 < 0)
            x0 = 0;
        if (m_CellCount.cx - 1 < x0)
            x0 = m_CellCount.cx - 1;

        s32 z0 = (s32)(m_InvCellDim * (shrinkZ + (pts[0].z - m_origin.z)));
        if (z0 < 0)
            z0 = 0;
        if (m_CellCount.cy - 1 < z0)
            z0 = m_CellCount.cy - 1;

        s32 x1 = (s32)(m_InvCellDim * (-shrinkX + (pts[1].x - m_origin.x)));
        if (x1 < 0)
            x1 = 0;
        if (m_CellCount.cx - 1 < x1)
            x1 = m_CellCount.cx - 1;
        x1++;

        s32 z1 = (s32)(m_InvCellDim * (-shrinkZ + (pts[1].z - m_origin.z)));
        if (z1 < 0)
            z1 = 0;
        if (m_CellCount.cy - 1 < z1)
            z1 = m_CellCount.cy - 1;
        z1++;

        node->AllocateAtomBasePtrs(x1 - x0, z1 - z0);

        for (s32 x = x0; x < x1; x++)
        {
            for (s32 z = z0; z < z1; z++)
            {
                CGridAtom* atom = NULL;

                if (m_AtomFreePtr != 0)
                    atom = m_FreeAtoms[m_AtomFreePtr--];

                atom->Ent = node;
                atom->Ent->InsertAtom(atom);

                CGridAtom** base = gridGetAtomBasePtr(x, z);
                CGridAtom* head = *base;

                if (head == NULL)
                {
                    atom->Prev = NULL;
                    *base = atom;
                    atom->Next = NULL;
                }
                else if (head->Next == NULL)
                {
                    atom->Prev = head;
                    head->Next = atom;
                    atom->Next = NULL;
                }
                else
                {
                    atom->Next = head->Next;
                    atom->Prev = head;
                    head->Next->Prev = atom;
                    head->Next = atom;
                }
            }
        }
    }
}

/* @socom-skeleton body gridRemoveNodeFromGrids__Q23zdb5CGridFPQ23zdb5CNode */
namespace zdb {
void CGrid::gridRemoveNodeFromGrids(CNode* node)
    {
        for (u32 i = 0; i < node->m_AtomCnt; i++)
        {
            CGridAtom* atom = node->GetAtom(i);

            if (!atom->Next)
            {
                atom->Prev->Next = NULL;
            }
            else
            {
                atom->Prev->Next = atom->Next;
                atom->Next->Prev = atom->Prev;
            }

            if (m_AtomFreePtr < m_AtomFreeCnt - 1)
            {
                atom->Ent = NULL;
                atom->Next = NULL;
                atom->Prev = NULL;
                m_FreeAtoms[++m_AtomFreePtr] = atom; /* pre-increment (0x2156f4, 0x216a34; was stored at the old top) */
            }
        }

        node->SetAtomCnt(0);
    }
}

/* @socom-skeleton stub SetCellBoundary__Q23zdb5CGridF6CPnt3D6CPnt3D */
/* the cell node at (x, z) of the clamped grid, as SetCellBoundary and GetNextCell inline it:
   the first atom of the cell's slot (gridGetAtomBasePtr) when its node is a cell (the asm
   compares the low half of m_type with 10) */
static zdb::CCell* GridCellAt(zdb::CGrid* grid, s32 x, s32 z)
{
	zdb::CGridAtom** base = grid->gridGetAtomBasePtr(x, z);

	if (base == NULL || *base == NULL)
		return NULL;

	zdb::CNode* node = (*base)->Ent;

	if (static_cast<u16>(node->m_type) != 10)
		return NULL;

	return static_cast<zdb::CCell*>(node);
}

zdb::CCell * zdb::CGrid::SetCellBoundary(CPnt3D lo, CPnt3D hi)
{
	/* 0x216880: the cells under the box (x and z of its corners) for GetNextCell; returns the
	   first one */
	gridGetGridXandZIndex(&xMinCell, &zMinCell, lo.x, lo.z);
	gridGetGridXandZIndex(&xMaxCell, &zMaxCell, hi.x, hi.z);
	xCurCell = xMinCell;
	zCurCell = zMinCell;
	return GridCellAt(this, xCurCell, zCurCell);
}

/* @socom-skeleton stub GetNextCell__Q23zdb5CGridFv */
zdb::CCell * zdb::CGrid::GetNextCell()
{
	/* 0x216700: the next cell of the SetCellBoundary range, row by row (x fastest); NULL past
	   the range. ELF quirk kept: a slot without a cell node also returns NULL, which ends the
	   callers' walks early. */
	xCurCell++;

	if (!(xMaxCell < xCurCell))
		return GridCellAt(this, xCurCell, zCurCell);

	xCurCell = xMinCell;
	zCurCell++;

	if (zMaxCell < zCurCell)
		return NULL;

	return GridCellAt(this, xCurCell, zCurCell);
}

/* @socom-skeleton body addOrderedCellAtom__Q23zdb5CGridFiib */
namespace zdb {
void CGrid::addOrderedCellAtom(s32 ix, s32 iy, bool force)
    {
        /* 0x216570: queue the cell at (ix, iy) once per tick, inside the traversal extents
           and (unless forced) not culled by gridCellOut; its ring is the Manhattan
           distance from the view cell. */
        if (ix < m_ix || ix >= m_ixb || iy < m_iz || iy >= m_izb)
            return;

        s32 x = ix;
        if (x < 0)
            x = 0;

        s32 cx = m_CellCount.cx;
        s32 xMax = cx - 1;
        if (x <= xMax)
            xMax = x;

        s32 z = iy;
        if (z < 0)
            z = 0;

        s32 zMax = m_CellCount.cy - 1;
        if (z <= zMax)
            zMax = z;

        CGridAtom* atom = m_Atoms[xMax + zMax * cx];

        if (atom == NULL)
            return;

        if (atom->Ent->m_TickNum >= m_TickNum)
            return;

        if (!force && gridCellOut(ix, iy))
            return;

        atom->Ent->m_TickNum = m_TickNum;

        CCell::GRIDCELLATOM* entry = &m_orderedCells.m_Atoms[m_orderedCells.m_gridCellAtomCnt];
        entry->cellAtom = atom;
        s32 dx = abs(ix - m_orderedCells.m_viewX);
        entry->ring = dx + abs(iy - m_orderedCells.m_viewZ);
        entry->x = ix;
        entry->z = iy;
        m_orderedCells.m_gridCellAtomCnt++;
    }
}

/* @socom-skeleton body buildOrderedCellAtomList__Q23zdb5CGridFPC6CPnt3D */
namespace zdb {
void CGrid::buildOrderedCellAtomList(const CPnt3D* point)
    {
        /* 0x2163a0: breadth-first ring walk out from the view cell; each pass expands the
           four neighbours of every cell of the current ring, until a pass adds nothing or
           the list holds MAX_NUM_CELL_ATOMS entries. */
        m_orderedCells.m_gridCellAtomCnt = 0;
        m_orderedCells.m_rt_gridCellAtomCnt = 0;

        s32 x = (s32)(m_InvCellDim * ((point->x - m_origin.x) + 0.0001f));
        if (x < 0)
            x = 0;

        s32 viewX = m_CellCount.cx - 1;
        if (x <= viewX)
            viewX = x;

        m_orderedCells.m_viewX = viewX;

        s32 z = (s32)(m_InvCellDim * ((point->z - m_origin.z) + 0.0001f));
        if (z < 0)
            z = 0;

        s32 viewZ = m_CellCount.cy - 1;
        if (z <= viewZ)
            viewZ = z;

        m_orderedCells.m_viewZ = viewZ;

        addOrderedCellAtom(viewX, viewZ, true);

        s32 ring = 0;
        s32 i = 0;
        CCell::GRIDCELLATOM* entry = &m_orderedCells.m_Atoms[0];
        bool added = true;

        while (added)
        {
            s32 count = m_orderedCells.m_gridCellAtomCnt;

            if (count >= MAX_NUM_CELL_ATOMS)
                break;

            CCell::GRIDCELLATOM* next = &m_orderedCells.m_Atoms[count];

            while (entry->ring == ring)
            {
                s32 ex = entry->x;
                s32 ez = entry->z;
                addOrderedCellAtom(ex - 1, ez, false);
                addOrderedCellAtom(ex + 1, ez, false);
                addOrderedCellAtom(ex, ez - 1, false);
                addOrderedCellAtom(ex, ez + 1, false);
                i++;
                entry = &m_orderedCells.m_Atoms[i];
            }

            entry = next;
            i = count;
            ring++;
            added = count != m_orderedCells.m_gridCellAtomCnt;
        }
    }
}

/* @socom-skeleton body SetTraversalExtents__Q23zdb5CGridFPC6CPnt3Dib */
namespace zdb {
void CGrid::SetTraversalExtents(const CPnt3D* point, s32 count, bool lineWalk)
    {
        /* 0x216140: copy up to five boundary points and take the cell rectangle that
           holds them ([m_ix, m_ixb) x [m_iz, m_izb)). */
        m_LineWalk = lineWalk;

        if (count < 0)
            count = 0;

        if (count > 5)
            count = 5;

        m_PntCnt = count;

        s32 x = (s32)(m_InvCellDim * ((point->x - m_origin.x) + 0.0001f));
        if (x < 0)
            x = 0;

        s32 cell = m_CellCount.cx - 1;
        if (x <= cell)
            cell = x;

        m_ixb = cell;
        m_ix = cell;

        s32 z = (s32)(m_InvCellDim * ((point->z - m_origin.z) + 0.0001f));
        if (z < 0)
            z = 0;

        cell = m_CellCount.cy - 1;
        if (z <= cell)
            cell = z;

        m_izb = cell;
        m_iz = cell;

        for (s32 i = 0; i < count; i++)
        {
            const CPnt3D* p = &point[i];

            m_Pnts[i].x = p->x;
            m_Pnts[i].y = p->y;
            m_Pnts[i].z = p->z;

            f32 inv = m_InvCellDim;

            s32 px = (s32)(inv * ((p->x - m_origin.x) + 0.0001f));
            if (px < 0)
                px = 0;

            s32 cx = m_CellCount.cx - 1;
            if (px <= cx)
                cx = px;

            s32 pz = (s32)(inv * ((p->z - m_origin.z) + 0.0001f));
            if (pz < 0)
                pz = 0;

            s32 cz = m_CellCount.cy - 1;
            if (pz <= cz)
                cz = pz;

            if (cx <= m_ix)
                m_ix = cx;

            if (cz <= m_iz)
                m_iz = cz;

            if (m_ixb <= cx)
                m_ixb = cx;

            if (m_izb <= cz)
                m_izb = cz;
        }

        m_ixb++;
        m_izb++;
    }
}

/* @socom-skeleton body SetTraversalBoundaryOrdered__Q23zdb5CGridFPC6CPnt3DPC6CPnt3Dib */
namespace zdb {
void CGrid::SetTraversalBoundaryOrdered(const CPnt3D* point, const CPnt3D* boundary, s32 count, bool lineWalk)
    {
        /* 0x215fb0: one point queues just its cell; a polygon gets unit edge normals in
           xz and the ring-ordered cell list from the view point. */
        SetTraversalExtents(boundary, count, lineWalk);

        if (count == 1)
        {
            s32 x;
            s32 z;

            m_orderedCells.m_gridCellAtomCnt = 0;
            m_orderedCells.m_rt_gridCellAtomCnt = 0;
            gridGetGridXandZIndex(&x, &z, boundary->x, boundary->z);
            addOrderedCellAtom(x, z, true);
            m_TickNum++;
        }
        else
        {
            for (s32 i = 0; i < m_PntCnt; i++)
            {
                s32 j = (i + 1) % m_PntCnt;

                m_Edge[i].z = m_Pnts[i].x - m_Pnts[j].x;
                m_Edge[i].x = m_Pnts[j].z - m_Pnts[i].z;

                f32 len = sqrtf(m_Edge[i].x * m_Edge[i].x + m_Edge[i].z * m_Edge[i].z);

                if (len != 0.0f)
                {
                    f32 inv = 1.0f / len;
                    m_Edge[i].z *= inv;
                    m_Edge[i].x *= inv;
                }
            }

            m_TickNum++;
            buildOrderedCellAtomList(point);
            m_TickNum++;
        }
    }
}

/* @socom-skeleton body SetTraversalBoundary__Q23zdb5CGridFPC6CPnt3Dib */
namespace zdb {
void CGrid::SetTraversalBoundary(const CPnt3D* point, s32 tick, bool lineWalk)
    {
        SetTraversalExtents(point, tick, lineWalk);

        if (tick == 1)
        {
            m_TickNum++;
            return;
        }

        /* 0x215e80: unit edge normals in xz of the boundary polygon (was an empty loop) */
        for (s32 i = 0; i < m_PntCnt; i++)
        {
            s32 j = (i + 1) % m_PntCnt;

            m_Edge[i].z = m_Pnts[i].x - m_Pnts[j].x;
            m_Edge[i].x = m_Pnts[j].z - m_Pnts[i].z;

            f32 len = sqrtf(m_Edge[i].x * m_Edge[i].x + m_Edge[i].z * m_Edge[i].z);

            if (len != 0.0f)
            {
                f32 inv = 1.0f / len;
                m_Edge[i].z *= inv;
                m_Edge[i].x *= inv;
            }
        }

        m_TickNum++;
    }
}

/* @socom-skeleton body gridCellOut__Q23zdb5CGridFii */
namespace zdb {
bool CGrid::gridCellOut(s32 ix, s32 iy)
    {
        /* 0x215d40: true when the centre of cell (ix, iy) lies more than m_GridCellTol
           outside an edge of the boundary polygon (or, walking a line, beyond either side). */
        m_CurCellOut = 0;

        if (m_PntCnt == 1)
            return false;

        if (m_PntCnt == 2 && !m_LineWalk)
            return false;

        f32 half = 0.5f * m_CellDim;
        f32 cx = half + (m_origin.x + (f32)ix * m_CellDim);
        f32 cz = half + (m_origin.z + (f32)iy * m_CellDim);

        m_CurCellOut = 1;

        for (s32 i = 0; i < m_PntCnt; i++)
        {
            f32 d = (cx - m_Pnts[i].x) * m_Edge[i].x + (cz - m_Pnts[i].z) * m_Edge[i].z;

            if (d < -m_GridCellTol)
                return true;

            if (m_LineWalk && !(d <= m_GridCellTol))
                return true;
        }

        m_CurCellOut = 0;

        if (m_PntCnt >= 3)
            m_RowCellIn = 1;

        return false;
    }
}

/* @socom-skeleton body StartTraversal__Q23zdb5CGridFv */
namespace zdb {
CGridAtom* CGrid::StartTraversal()
    {
        m_xx = m_ix;
        m_zz = m_iz;
        m_iz_start = m_zz;
        m_iz_next_row = m_izb;
        m_NextAtom = NULL;
        m_zz--;
        m_RowCellIn = 0;
        m_CurCellOut = 1;
        m_iz_dir = 1;
        return m_NextAtom = GetNextAtom();
    }
}

/* @socom-skeleton body StartTraversalOrdered__Q23zdb5CGridFv */
namespace zdb {
CGridAtom* CGrid::StartTraversalOrdered()
    {
        /* 0x215ca0 */
        m_NextAtom = NULL;
        m_NextAtom = GetNextAtomOrdered();
        return m_NextAtom;
    }
}

/* @socom-skeleton body gridGetNextIndex__Q23zdb5CGridFv */
namespace zdb {
bool CGrid::gridGetNextIndex()
    {
        bool valid = false;

        if (m_PntCnt < 3)
        {
            if (m_zz < m_izb - 1)
            {
                valid = true;
                m_zz++;
            }
            else if (m_xx < m_ixb - 1)
            {
                valid = true;
                m_xx++;
                m_zz = m_iz;
                m_RowCellIn = 0;
            }
        }
        else
        {
            if (m_CurCellOut == 0 && m_zz < m_iz_next_row)
                m_iz_next_row = m_zz;

            if (m_iz_dir < 0)
            {
                if (m_CurCellOut == 0 && m_iz < m_zz)
                {
                    m_zz--;
                    return true;
                }

                m_zz = m_iz_start;
                m_iz_dir = 1;
                m_CurCellOut = 0;
            }

            if (m_RowCellIn == 0 || m_CurCellOut == 0 && m_zz < m_izb - 1)
            {
                valid = true;
                m_zz++;
            }
            else if (m_xx < m_ixb - 1)
            {
                m_xx++;

                if (m_iz_next_row == m_izb)
                {
                    m_zz = m_iz;
                    m_iz_dir = 1;
                }
                else
                {
                    m_zz = m_iz_next_row;

                    if (m_iz < m_zz)
                        m_zz++;

                    m_iz_dir = -1;
                }

                valid = true;
                m_iz_next_row = m_izb;
                m_iz_start = m_zz;
                m_RowCellIn = 0;
            }
            else
            {
                m_RowCellIn = 0;
                m_CurCellOut = 0;
                valid = false;
            }
        }

        return valid;
    }
}

/* @socom-skeleton stub gridGetGridXandZIndex__Q23zdb5CGridFPiPiff */
void zdb::CGrid::gridGetGridXandZIndex(int *x, int *z, float px, float pz)
{
	/* 0x215a30: VU0 vftoi0 (truncating) of the scaled offsets, clamped to the grid */
	s32 ix = (s32)(m_InvCellDim * (px - m_origin.x));
	s32 iz = (s32)(m_InvCellDim * (pz - m_origin.z));

	*x = ix < 0 ? 0 : ix;

	if (m_CellCount.cx <= *x)
		*x = m_CellCount.cx - 1;

	*z = iz < 0 ? 0 : iz;

	if (m_CellCount.cy <= *z)
		*z = m_CellCount.cy - 1;
}

/* @socom-skeleton body GetNextAtom__Q23zdb5CGridFv */
namespace zdb {
CGridAtom* CGrid::GetNextAtom()
    {
        /* 0x215910: the next atom of the current cell's chain, else the first atom of the
           next cell (gridGetNextIndex) that the boundary does not cull; only active nodes
           not yet visited this tick are returned, and are marked visited. Was a TODO. */
        for (;;)
        {
            if (m_NextAtom == NULL)
            {
                if (!gridGetNextIndex())
                    return NULL;

                if (gridCellOut(m_xx, m_zz))
                    m_NextAtom = NULL;
                else
                    m_NextAtom = *gridGetAtomBasePtr(m_xx, m_zz);
            }
            else
            {
                m_NextAtom = m_NextAtom->Next;
            }

            if (m_NextAtom == NULL)
                continue;

            CNode* node = m_NextAtom->Ent;

            if (!node->m_active || !(node->m_TickNum < m_TickNum))
                continue;

            node->m_TickNum = m_TickNum;
            return m_NextAtom;
        }
    }
}

/* @socom-skeleton body GetNextAtomOrdered__Q23zdb5CGridFv */
namespace zdb {
CGridAtom* CGrid::GetNextAtomOrdered()
    {
        /* 0x215860: follow the current cell's atom chain, then the next queued cell (whose
           ring becomes m_ring); skip inactive nodes and nodes already visited this tick. */
        for (;;)
        {
            if (m_NextAtom == NULL)
            {
                s32 i = m_orderedCells.m_rt_gridCellAtomCnt;

                if (i == m_orderedCells.m_gridCellAtomCnt)
                    return NULL;

                m_ring = m_orderedCells.m_Atoms[i].ring;
                m_orderedCells.m_rt_gridCellAtomCnt = i + 1;
                m_NextAtom = m_orderedCells.m_Atoms[i].cellAtom;
            }
            else
            {
                m_NextAtom = m_NextAtom->Next;
            }

            if (m_NextAtom == NULL)
                continue;

            CNode* node = m_NextAtom->Ent;

            if (!node->m_active)
                continue;

            if (node->m_TickNum >= m_TickNum)
                continue;

            node->m_TickNum = m_TickNum;
            return m_NextAtom;
        }
    }
}

/* @socom-skeleton stub Insert__Q23zdb5CGridFPQ23zdb5CNode */
void zdb::CGrid::Insert(zdb::CNode *node)
{
	/* 0x215850: tail call */
	gridAddNodeToGrids(node);
}

/* @socom-skeleton stub Remove__Q23zdb5CGridFPQ23zdb5CNode */
void zdb::CGrid::Remove(zdb::CNode *node)
{
	/* 0x215760: unlink every atom of the node from its cell list, return it to the free
	   list while there is room, then forget and free the node's atom array */
	for (s32 i = 0; i < node->m_AtomCnt; i++)
	{
		CGridAtom* atom = node->GetAtom(i);

		if (!atom->Next)
		{
			atom->Prev->Next = NULL;
		}
		else
		{
			atom->Prev->Next = atom->Next;
			atom->Next->Prev = atom->Prev;
		}

		if (m_AtomFreePtr < m_AtomFreeCnt - 1)
		{
			atom->Ent = NULL;
			atom->Next = NULL;
			atom->Prev = NULL;
			m_FreeAtoms[++m_AtomFreePtr] = atom;
		}
	}

	node->SetAtomCnt(0);
	node->FreeAtom();
}

/* @socom-skeleton body Update__Q23zdb5CGridFPQ23zdb5CNode */
namespace zdb {
void CGrid::Update(CNode* node)
    {
        for (u32 i = 0; i < node->m_AtomCnt; i++)
        {
            CGridAtom* atom = node->GetAtom(i);

            if (!atom->Next)
            {
                atom->Prev->Next = NULL;
            }
            else
            {
                atom->Prev->Next = atom->Next;
                atom->Next->Prev = atom->Prev;
            }

            if (m_AtomFreePtr < m_AtomFreeCnt - 1)
            {
                atom->Ent = NULL;
                atom->Next = NULL;
                atom->Prev = NULL;
                m_FreeAtoms[++m_AtomFreePtr] = atom; /* pre-increment (0x2156f4, 0x216a34; was stored at the old top) */
            }
        }

        node->SetAtomCnt(0);
        gridAddNodeToGrids(node);
    }
}

/* @socom-skeleton body Create__Q23zdb5CGridFPQ23zdb6CWorldPCQ23zdb15tag_GRID_PARAMS */
namespace zdb {
bool CGrid::Create(CWorld* world, const tag_GRID_PARAMS* params)
    {
        CBBox bbox;
        
        m_world = world;
        m_posts = params->m_posts;

        if (m_world->m_use_parent_bbox)
        {
            CNode* parent = m_world->m_parent;
            bbox = parent->m_bbox;

            if (m_world->m_use_parent_bbox)
            {
                bbox = *parent->GetBBox();
            }
        }
        else
        {
            bbox = m_world->m_bbox;
        }

        m_origin = bbox.m_min;

        m_CellCount.cx = params->m_CellCount.cx;
        m_CellCount.cy = params->m_CellCount.cy;
        m_CellDim = params->m_CellDim;

        m_extents.top = 0.0f;
        m_extents.left = 0.0f;
        m_extents.right = m_CellDim * m_CellCount.cx;
        m_extents.bottom = m_CellDim * m_CellCount.cy;
        
        m_GridCellTol = 0.5f * sqrtf(2.0f * (m_CellDim * m_CellDim)); /* 0x2153e4: half the cell diagonal (the 0.5 was missing) */
        m_ClutterTol = 0.0f;
        m_InvCellDim = 1.0f / m_CellDim;
        
        m_TickNum = -1;
        
        m_AtomCnt = 16384;
        m_AtomFreeCnt = m_AtomCnt;
        m_AtomBuf = static_cast<CGridAtom*>(zmalloc(m_AtomCnt * 12));
        m_FreeAtoms = static_cast<CGridAtom**>(zmalloc(m_AtomCnt << 2));

        /* 0x21545c: the free list holds every atom of the buffer. Was `m_FreeAtoms + ex`
           with ex stepping by 4 - pointer arithmetic on CGridAtom** - which filled every
           fourth slot, wrote 3/4 of the list past its end and left the rest garbage. */
        for (s32 i = 0; i < m_AtomCnt; i++)
            m_FreeAtoms[i] = &m_AtomBuf[i];

        m_AtomFreePtr = m_AtomCnt - 1;

        m_Atoms = static_cast<CGridAtom**>(zmalloc(m_CellCount.cx * m_CellCount.cy * sizeof(CGridAtom)));

        world->ReserveChildren(m_CellCount.cy * m_CellCount.cx);

        s32 i = 0;
        
        for (s32 y = 0; y < m_CellCount.cy; y++)
        {
            for (s32 x = 0; x < m_CellCount.cx; x++)
            {
                s32 cellidx = 0;
                s32 cx = 0;
                s32 cy = 0;
                CPnt3D cellpos;
                char buf[24];

                cellpos.y = m_origin.y;
                cellpos.x = m_origin.x + (x * m_CellDim);
                cellpos.z = m_origin.z + (y * m_CellDim);

                cellidx = x;

                if (x < 0)
                {
                    cellidx = 0;
                }

                if (cellidx <= m_CellCount.cx - 1)
                {
                    cx = cellidx;
                }

                cellidx = y;

                if (y < 0)
                {
                    cellidx = 0;
                }

                if (cellidx <= m_CellCount.cy - 1)
                {
                    cy = cellidx;
                }

                m_Atoms[cx + cy * m_CellCount.cx] = NULL;

                CCell* cell = new CCell(&cellpos, m_CellDim);
                snprintf(buf, 24, "cell%06d", i);
                cell->SetName(buf);
                world->AddChild(cell);
                i++;
            }
        }

        return true;
    }
}

/* @socom-skeleton stub Destroy__Q23zdb5CGridFv */
void zdb::CGrid::Destroy()
{
	/* 0x215120: the world's non-cell children leave the grid, the cells are deleted
	   (through the world's virtual DeleteChild), then the atom tables are freed */
	if (m_world != NULL)
	{
		CNodeVector cells;
		CNodeVector others;
		m_world->Segregate_CCells(m_world, cells, others);

		for (CNodeVector::iterator it = others.begin(); it != others.end(); ++it)
		{
			gridRemoveNodeFromGrids(*it);
			(*it)->FreeAtom();
		}

		for (CNodeVector::iterator it = cells.begin(); it != cells.end(); ++it)
		{
			CNode* cell = *it;
			m_world->DeleteChild(cell);

			if (cell != NULL)
				delete cell;
		}

		cells.erase(cells.begin(), cells.end());
		m_world = NULL;
	}

	if (m_Atoms != NULL)
		_free(m_Atoms, "grid_main.cpp", 0x488);

	m_Atoms = NULL;

	if (m_AtomBuf != NULL)
		_free(m_AtomBuf, "grid_main.cpp", 0x489);

	m_AtomBuf = NULL;

	if (m_FreeAtoms != NULL)
		_free(m_FreeAtoms, "grid_main.cpp", 0x48a);

	m_FreeAtoms = NULL;
}

